<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT t.*,m.matter_reference,m.subject FROM tasks t LEFT JOIN matters m ON m.id=t.matter_id WHERE t.id=?');$stmt->execute([$id]);$task=$stmt->fetch();if(!$task){http_response_code(404);exit('Task not found.');}$pageTitle='Task | AEP';$activeNav='tasks';require __DIR__.'/includes/header.php';?><div class="card" style="max-width:850px;margin:auto"><div class="actions" style="justify-content:space-between"><div><span class="badge"><?php echo aep_h($task['status']);?></span><h1><?php echo aep_h($task['title']);?></h1></div><a class="btn secondary" href="task_edit.php?id=<?php echo $id;?>">Edit</a></div><p><?php echo nl2br(aep_h($task['description']));?></p><p class="muted">Due: <?php echo aep_h($task['due_date']?:'Not set');?><?php if($task['matter_reference']):?> · Matter: <a href="matter_view.php?id=<?php echo (int)$task['matter_id'];?>"><?php echo aep_h($task['matter_reference']);?></a><?php endif;?></p></div><?php require __DIR__.'/includes/footer.php';?>
